CREATE TABLE ezgmaplocation (contentobject_attribute_id INT DEFAULT 0 NOT NULL, contentobject_version INT DEFAULT 0 NOT NULL, latitude DOUBLE PRECISION DEFAULT '0' NOT NULL, longitude DOUBLE PRECISION DEFAULT '0' NOT NULL, address VARCHAR(150) DEFAULT NULL, INDEX latitude_longitude_key (latitude, longitude), PRIMARY KEY(contentobject_attribute_id, contentobject_version)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
